                DispatchBlockReason: "LEGACY_POLICY_V1" | "LEGACY_MISSING_MANIFEST_PIN" | "LEGACY_MISSING_TARGET_REFS" | "LEGACY_ACTOR" | "LEGACY_PROPOSER_LABEL" | "LEGACY_TARGET_PROJECTION";
