            attempt: number;
            /** @description Kết thúc chuẩn hóa của lời gọi thất bại; vắng khi chưa có lời gọi (hết ngân sách). */
            finish_reason?: components["schemas"]["FinishReason"];
            provider?: components["schemas"]["Provider"];
            model?: string;
            session_id?: components["schemas"]["Id"];
